// Package home is the realm behind https://gno.land/u/moul.
//
// gnoweb builds a user profile page by calling Render("") on the realm at the
// exact path /r/<username>/home (gno.land/pkg/gnoweb/handler_http.go,
// GetUserView) and embedding the result as the profile body. There is no
// version resolution in that lookup, which is why this realm (alone in this
// repo) carries no /vN suffix: the bare path IS the interface with gnoweb,
// and gno.land/r/moul/home/v0 would never be found.
//
// # Slots
//
// The page is not hard-coded. It is assembled from SLOTS: named markdown
// fragments in an avl tree, each written by its own Set call, so updating one
// paragraph is one small transaction instead of a redeploy.
//
// The layout is itself a slot ("layout"), so the shape of the page (headings,
// order, what appears at all) changes without touching the code.
// p/moul/dynreplacer fills every :slug: placeholder found in the layout, lazily:
// a slot whose placeholder is absent from the layout costs nothing to render.
//
// Substitution is SINGLE-PASS and non-recursive. A placeholder inside a slot
// body is left alone, so no slot can expand into another and no cycle exists.
// Two registered placeholders can never be prefixes of one another either
// (every one is :slug: and a slug may not contain ':'), so the result does not
// depend on registration order.
//
// A placeholder with no matching slot survives into the output verbatim. That
// is deliberate: a missing section should be visible, not silently blank.
//
// # Versioning
//
// gnomod.toml declares private = true, which lets the creator re-add the
// package at this path. That redeploy re-runs init() and RESETS everything
// here, so the markdown under content/ is the source of truth and
// tools/gnohome pushes the slots back afterwards. The intended path is that this
// never happens: slots cover content, and the layout slot covers presentation.
package home

import (
	"crypto/sha256"
	"encoding/hex"
	"strconv"
	"strings"

	"gno.land/p/nt/avl/v0"
)

// admin is the only address allowed to write. Deliberately a constant and not
// transferable ownership: this realm is one person's profile page, and the
// same address is the only one the chain lets redeploy it.
const admin = address("g1manfred47kzduec920z88wfr64ylksmdcedlf5")

// layoutSlug names the slot used as the page template.
const layoutSlug = "layout"

// realmPath is this realm's own path. Written out rather than read from
// unsafe.CurrentRealm() because it is also the interface with gnoweb (see the
// package doc): the constant is the thing that must not drift, so it is stated
// once and every other use points here.
const realmPath = "gno.land/r/moul/home"

// maxSlugLen bounds a slug so an index row stays readable and a key stays cheap.
const maxSlugLen = 64

var (
	slots = avl.NewTree() // slug -> *slot
	rev   int             // total number of writes, bumped by every mutation
)

type slot struct {
	body    string
	rev     int   // rev at the time of the last write to this slot
	updated int64 // block height of the last write
}

// reservedSlugs are placeholder names computed at render time from chain state.
// A slot may not take one, because it would shadow the computed value and make
// the page depend on callback registration order.
//
// The scan.* half comes from scan.gno's scanPlaceholders, so adding an explorer
// placeholder there reserves it here and cannot be forgotten.
var reservedSlugs = append(
	[]string{"chainid", "height", "owner", "realm", "rev", "slots"},
	scanPlaceholders...,
)

func assertAdmin(cur realm) {
	if cur.Previous().Address() != admin {
		panic("restricted to admin")
	}
}

// validSlug reports whether slug is a legal slot name: 1..maxSlugLen bytes of
// [a-z0-9._-]. The character set excludes ':' so a slug can never break out of
// its own :slug: placeholder, and excludes uppercase so a slot has one name.
func validSlug(slug string) bool {
	if len(slug) == 0 || len(slug) > maxSlugLen {
		return false
	}
	for i := 0; i < len(slug); i++ {
		c := slug[i]
		switch {
		case c >= 'a' && c <= 'z', c >= '0' && c <= '9':
		case c == '-', c == '_', c == '.':
		default:
			return false
		}
	}
	return true
}

func assertWritableSlug(slug string) {
	if !validSlug(slug) {
		panic("invalid slug: want 1-" + strconv.Itoa(maxSlugLen) + " bytes of [a-z0-9._-], got " + strconv.Quote(slug))
	}
	for _, r := range reservedSlugs {
		if slug == r {
			panic("reserved slug: " + slug + " is computed at render time")
		}
	}
}

// Set creates or replaces the slot named slug. This is the ordinary update: one
// slot, one transaction. Passing the empty body keeps the slot but empties it;
// use Delete to remove it.
func Set(cur realm, slug, body string) {
	assertAdmin(cur)
	assertWritableSlug(slug)
	rev++
	slots.Set(slug, &slot{body: body, rev: rev, updated: chainHeight()})
}

// Append adds to the end of a slot, creating it when absent. It exists for
// content too large to fit in one transaction: Set the first chunk, Append the
// rest. Ordinary updates should use Set, which is idempotent.
func Append(cur realm, slug, body string) {
	assertAdmin(cur)
	assertWritableSlug(slug)
	rev++
	prev := ""
	if v := slots.Get(slug); v != nil {
		prev = v.(*slot).body
	}
	slots.Set(slug, &slot{body: prev + body, rev: rev, updated: chainHeight()})
}

// Delete removes a slot. Deleting the layout slot restores the built-in
// default layout.
func Delete(cur realm, slug string) {
	assertAdmin(cur)
	if _, removed := slots.Remove(slug); !removed {
		panic("no such slot: " + slug)
	}
	rev++
}

// Get returns a slot body, or "" when the slot does not exist.
func Get(slug string) string {
	v := slots.Get(slug)
	if v == nil {
		return ""
	}
	return v.(*slot).body
}

// Revision returns the total number of writes this realm has accepted. It
// changes on every mutation, so a client can cheaply tell "nothing moved".
func Revision() int {
	return rev
}

// Manifest returns one tab-separated line per slot:
//
//	<slug>\t<rev>\t<len>\t<sha256 of body, hex>
//
// It is the diff surface tools/gnohome queries with vm/qeval: one read tells it
// exactly which local file is out of date, without downloading any body.
func Manifest() string {
	var b strings.Builder
	slots.Iterate("", "", func(key string, value any) bool {
		s := value.(*slot)
		sum := sha256.Sum256([]byte(s.body))
		b.WriteString(key)
		b.WriteString("\t")
		b.WriteString(strconv.Itoa(s.rev))
		b.WriteString("\t")
		b.WriteString(strconv.Itoa(len(s.body)))
		b.WriteString("\t")
		b.WriteString(hex.EncodeToString(sum[:]))
		b.WriteString("\n")
		return false
	})
	return b.String()
}

package home

import (
	"strings"
	"testing"

	"gno.land/p/nt/avl/v0"
	"gno.land/p/nt/testutils/v0"
	"gno.land/p/nt/uassert/v0"
)

var stranger = testutils.TestAddress("mallory")

// reset clears realm state. Realm globals live for the whole test binary, so
// every test that reads Render or Manifest starts from a known tree.
func reset() {
	slots = avl.NewTree()
	rev = 0
}

// seed writes a slot without going through the admin check, for tests (and the
// Example) that only care about the rendering side.
func seed(slug, body string) {
	rev++
	slots.Set(slug, &slot{body: body, rev: rev, updated: 0})
}

func TestSetGetDelete(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(admin))

	Set(cross(cur), "bio", "Building on gno.")
	uassert.Equal(t, "Building on gno.", Get("bio"))
	uassert.Equal(t, 1, Revision())

	// Set is idempotent in shape: a second write replaces, never appends.
	Set(cross(cur), "bio", "Still building.")
	uassert.Equal(t, "Still building.", Get("bio"))
	uassert.Equal(t, 2, Revision())

	Delete(cross(cur), "bio")
	uassert.Equal(t, "", Get("bio"), "a deleted slot reads as empty")
	uassert.Equal(t, 3, Revision())

	uassert.AbortsWithMessage(t, cur, "no such slot: bio", func() {
		Delete(cross(cur), "bio")
	})
}

func TestAppendChunks(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(admin))

	// The escape hatch for a body too large for one transaction.
	Set(cross(cur), "long", "part one. ")
	Append(cross(cur), "long", "part two.")
	uassert.Equal(t, "part one. part two.", Get("long"))

	// Append creates the slot when it is absent.
	Append(cross(cur), "fresh", "hello")
	uassert.Equal(t, "hello", Get("fresh"))
}

func TestWritesAreAdminOnly(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(stranger))

	uassert.AbortsWithMessage(t, cur, "restricted to admin", func() {
		Set(cross(cur), "bio", "pwned")
	})
	uassert.AbortsWithMessage(t, cur, "restricted to admin", func() {
		Append(cross(cur), "bio", "pwned")
	})
	uassert.AbortsWithMessage(t, cur, "restricted to admin", func() {
		Delete(cross(cur), "bio")
	})
	uassert.Equal(t, "", Get("bio"))
}

func TestSlugRules(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(admin))

	uassert.True(t, validSlug("bio"))
	uassert.True(t, validSlug("now.2026-09"))
	uassert.True(t, validSlug("latest_packages"))
	uassert.False(t, validSlug(""), "empty")
	uassert.False(t, validSlug("Bio"), "uppercase: a slot must have one name")
	uassert.False(t, validSlug("a b"), "space")
	uassert.False(t, validSlug("a:b"), "a colon would break out of the :slug: placeholder")
	uassert.False(t, validSlug(strings.Repeat("a", maxSlugLen+1)), "too long")

	uassert.AbortsContains(t, cur, "invalid slug", func() {
		Set(cross(cur), "Bad Slug", "x")
	})

	// A reserved name would shadow a value computed from chain state.
	for _, name := range reservedSlugs {
		uassert.AbortsContains(t, cur, "reserved slug", func() {
			Set(cross(cur), name, "x")
		})
	}

	// "layout" is special but NOT reserved: it is a real, writable slot.
	Set(cross(cur), layoutSlug, "# hi")
	uassert.Equal(t, "# hi", Get(layoutSlug))
}

func TestManifestIsTheDiffSurface(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(admin))

	Set(cross(cur), "bio", "hello")
	Set(cross(cur), "alpha", "")

	// Sorted by slug (avl order), one line each, four tab-separated fields.
	lines := strings.Split(strings.TrimSuffix(Manifest(), "\n"), "\n")
	uassert.Equal(t, 2, len(lines))

	alpha := strings.Split(lines[0], "\t")
	uassert.Equal(t, 4, len(alpha))
	uassert.Equal(t, "alpha", alpha[0])
	uassert.Equal(t, "0", alpha[2], "byte length of an empty body")
	// sha256(""), pinning that the hash is over the body, not over a wrapper.
	uassert.Equal(t, "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", alpha[3])

	bio := strings.Split(lines[1], "\t")
	uassert.Equal(t, "bio", bio[0])
	uassert.Equal(t, "5", bio[2])
	// sha256("hello")
	uassert.Equal(t, "2cf24dba5fb0a30e26e83b2ac5b9e29e1b161e5c1fa7425e73043362938b9824", bio[3])
}

func TestRenderFillsTheLayoutSlot(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(admin))

	Set(cross(cur), layoutSlug, "# :owner:\n\n:bio:\n\n:missing:\n")
	Set(cross(cur), "bio", "Building on gno.")

	out := Render("")
	uassert.True(t, strings.Contains(out, "# "+admin.String()),
		"a computed placeholder is filled from chain state")
	uassert.True(t, strings.Contains(out, "Building on gno."),
		"a slot placeholder is filled from the tree")
	uassert.True(t, strings.Contains(out, ":missing:"),
		"an unmatched placeholder survives verbatim, so a gap is visible")
}

func TestRenderDoesNotRecurse(cur realm, t *testing.T) {
	reset()
	testing.SetRealm(testing.NewUserRealm(admin))

	// A slot body that looks like a placeholder must not expand: substitution
	// is one pass, which is what makes cycles impossible.
	Set(cross(cur), layoutSlug, ":a:")
	Set(cross(cur), "a", ":b:")
	Set(cross(cur), "b", "should not appear")

	uassert.Equal(t, ":b:", Render(""))
}

func TestRenderUnsetLayoutFallsBack(t *testing.T) {
	reset()
	out := Render("")
	uassert.True(t, strings.Contains(out, "No layout slot yet"))
	uassert.False(t, strings.Contains(out, ":slots:"),
		"the default layout must not leave its own placeholders unresolved")
	uassert.False(t, strings.Contains(out, ":rev:"))
	uassert.False(t, strings.Contains(out, ":height:"))
	uassert.False(t, strings.Contains(out, ":chainid:"))
}

func TestRenderSubPaths(t *testing.T) {
	reset()
	seed("bio", "Building on gno.")

	idx := Render("slots")
	uassert.True(t, strings.Contains(idx, "| [bio](/r/moul/home:slots/bio) |"))

	raw := Render("slots/bio")
	uassert.True(t, strings.Contains(raw, "Building on gno."))
	uassert.True(t, strings.Contains(raw, "16 bytes"))

	uassert.True(t, strings.Contains(Render("slots/nope"), "No slot named"))
	uassert.True(t, strings.Contains(Render("whatever"), "No such path"))
}

func TestRenderEmptyIndex(t *testing.T) {
	reset()
	uassert.True(t, strings.Contains(Render("slots"), "_no slots yet_"))
}

package home

import (
	"strconv"
	"strings"

	"chain/runtime"

	"gno.land/p/moul/dynreplacer/v0"
	"gno.land/r/moul/config/v1"
)

// defaultLayout is what renders before a layout slot exists, which is not only
// the very first deploy: a redeploy re-runs init() and wipes every slot, so
// this is also the page at the exact moment someone is restoring it. It uses
// only computed placeholders, so it never shows an unresolved :slug: of its own.
//
// It prints no gnokey command and no gas numbers, on purpose. The one it used
// to print offered 1000000ugnot against 20000000 gas: a ratio of 0.05 against a
// mainnet floor of 0.001, and gas_fee is deducted in full as offered and never
// refunded, so it asked for about fifty times what the write costs. The tooling
// was corrected and this string was not, which is the argument against having
// it at all. A command baked into a realm cannot be fixed without a redeploy,
// and the redeploy is the thing that wipes the slots. gnohome recomputes it
// from content/ and from the chain, so it cannot go stale.
const defaultLayout = "# gno.land/r/moul/home\n\n" +
	"No layout slot yet. A redeploy wipes every slot and `content/` is the source\n" +
	"of truth, so push them back with the tool rather than by hand:\n\n" +
	"    go -C tools tool gnohome tx -all\n\n" +
	"No gas numbers here on purpose: a command written into a realm goes stale and\n" +
	"cannot be corrected without another redeploy.\n\n" +
	"## Slots\n\n:slots:\n\n---\n\nrev :rev: · height :height: · :chainid:\n"

func chainHeight() int64 { return runtime.ChainHeight() }

// Render serves three views:
//
//	""            the assembled page, what https://gno.land/u/moul shows
//	"slots"       the slot index: name, size, revision, last write
//	"slots/<slug>" one slot's raw markdown, fenced
func Render(path string) string {
	switch {
	case path == "":
		return renderPage()
	case path == "slots":
		return renderIndex()
	case strings.HasPrefix(path, "slots/"):
		return renderSlot(strings.TrimPrefix(path, "slots/"))
	default:
		return "# Not found\n\nNo such path: " + strconv.Quote(path) +
			"\n\nTry [the slot index](/r/moul/home:slots).\n"
	}
}

// renderPage fills the layout. dynreplacer only invokes the callbacks whose
// placeholder actually occurs in the layout, so an unused slot is never even
// read out of the tree.
func renderPage() string {
	layout := Get(layoutSlug)
	if layout == "" {
		layout = defaultLayout
	}

	r := dynreplacer.New()

	// Computed from chain state. Registered first; assertWritableSlug keeps a
	// slot from ever taking one of these names, so nothing shadows them.
	r.RegisterCallback(":owner:", func() string { return admin.String() })
	r.RegisterCallback(":realm:", func() string { return realmPath })
	r.RegisterCallback(":chainid:", func() string { return runtime.ChainID() })
	r.RegisterCallback(":height:", func() string { return strconv.FormatInt(runtime.ChainHeight(), 10) })
	r.RegisterCallback(":rev:", func() string { return strconv.Itoa(rev) })
	r.RegisterCallback(":slots:", func() string { return slotLinks() })

	// The explorer links, which are computed the same way but come from
	// another realm's configuration. See scan.gno.
	registerScanCallbacks(r)

	// One callback per slot. The closure captures s, which is re-bound on each
	// iteration, so every callback sees its own slot.
	slots.Iterate("", "", func(key string, value any) bool {
		s := value.(*slot)
		r.RegisterCallback(":"+key+":", func() string { return s.body })
		return false
	})

	// The notice blocks, from gno.land/r/moul/config: a warning, a changelog
	// line or a bit of news, set either on every realm of moul's at once or on
	// this one alone, and empty by default. A pause banner rides along at the
	// top, so the page explains itself if this realm is ever held back.
	//
	// The path is passed explicitly rather than using config's zero-argument
	// TopBlock(). That form reads the caller off the stack, which is correct
	// here and is covered by config's own tests, but this realm's Render IS
	// gno.land/u/moul and it already states its own path: passing the constant
	// cannot be wrong, at no cost.
	return config.TopBlockFor(realmPath) + r.Replace(layout) + config.BottomBlockFor(realmPath)
}

// slotLinks is the :slots: placeholder: a bullet list of every slot, linking to
// its raw view.
func slotLinks() string {
	if slots.Size() == 0 {
		return "_no slots yet_"
	}
	var b strings.Builder
	slots.Iterate("", "", func(key string, value any) bool {
		b.WriteString("- [")
		b.WriteString(key)
		b.WriteString("](/r/moul/home:slots/")
		b.WriteString(key)
		b.WriteString(")\n")
		return false
	})
	return strings.TrimSuffix(b.String(), "\n")
}

func renderIndex() string {
	var b strings.Builder
	b.WriteString("# Slots\n\n")
	b.WriteString("rev ")
	b.WriteString(strconv.Itoa(rev))
	b.WriteString(" · ")
	b.WriteString(strconv.Itoa(slots.Size()))
	b.WriteString(" slot(s)\n\n")
	if slots.Size() == 0 {
		b.WriteString("_no slots yet_\n")
		return b.String()
	}
	b.WriteString("| slot | bytes | rev | height |\n")
	b.WriteString("| --- | ---: | ---: | ---: |\n")
	slots.Iterate("", "", func(key string, value any) bool {
		s := value.(*slot)
		b.WriteString("| [")
		b.WriteString(key)
		b.WriteString("](/r/moul/home:slots/")
		b.WriteString(key)
		b.WriteString(") | ")
		b.WriteString(strconv.Itoa(len(s.body)))
		b.WriteString(" | ")
		b.WriteString(strconv.Itoa(s.rev))
		b.WriteString(" | ")
		b.WriteString(strconv.FormatInt(s.updated, 10))
		b.WriteString(" |\n")
		return false
	})
	return b.String()
}

func renderSlot(slug string) string {
	v := slots.Get(slug)
	if v == nil {
		return "# Not found\n\nNo slot named " + strconv.Quote(slug) +
			".\n\nTry [the slot index](/r/moul/home:slots).\n"
	}
	s := v.(*slot)
	var b strings.Builder
	b.WriteString("# ")
	b.WriteString(slug)
	b.WriteString("\n\n")
	b.WriteString(strconv.Itoa(len(s.body)))
	b.WriteString(" bytes · rev ")
	b.WriteString(strconv.Itoa(s.rev))
	b.WriteString(" · written at height ")
	b.WriteString(strconv.FormatInt(s.updated, 10))
	b.WriteString("\n\n```\n")
	b.WriteString(s.body)
	if !strings.HasSuffix(s.body, "\n") {
		b.WriteString("\n")
	}
	b.WriteString("```\n")
	return b.String()
}

package home

// ExampleRender pins the assembled page. It seeds state directly (rather than
// through Set) so the example takes no `cur realm`, and it uses only
// non-volatile placeholders so the golden output does not depend on the test
// machine's block height or chain id.
func ExampleRender() {
	reset()
	seed("layout", "# :owner:\n\n:bio:\n\n## Packages\n\n:packages:\n")
	seed("bio", "Building on gno.")
	seed("packages", "- p/moul/dynreplacer\n- r/moul/home")
	print(Render(""))
	// Output:
	// # g1manfred47kzduec920z88wfr64ylksmdcedlf5
	//
	// Building on gno.
	//
	// ## Packages
	//
	// - p/moul/dynreplacer
	// - r/moul/home
}

package home

import (
	"strings"

	"chain/runtime"

	"gno.land/p/moul/dynreplacer/v0"
	"gno.land/p/moul/mygnoscan/v0"
	"gno.land/r/moul/config/v1"
)

// This file is the explorer half of the page: a handful of computed
// placeholders that turn what this realm already knows (its own path, its
// owner, the block it is rendering at) into links a reader can click.
//
// They are COMPUTED, not slots, so they are always current: the layout slot
// says where a link goes on the page, and nothing in storage has to be
// rewritten when the answer changes.
//
// The explorer they point at comes from gno.land/r/moul/config, not from a
// constant here. That is the whole point of the indirection: moving every one
// of moul's realms to a different explorer is one transaction against config,
// not a redeploy of each realm that links to one. When config has no setting,
// mygnoscan.DefaultBase answers, so this realm renders correctly on a chain
// where nothing was ever configured.

// scanPlaceholders are the reserved slugs this file answers for. They are
// listed in reservedSlugs (home.gno) so a slot can never take one of these
// names and shadow the computed value.
var scanPlaceholders = []string{
	"scan",       // the explorer base URL, as plain text
	"scan.realm", // this realm on the explorer
	"scan.me",    // the owner's account page
	"scan.block", // the block this render is happening at
	"scan.links", // the three above, on one line
}

// scanner returns the configured link builder.
//
// config.Scanner() is a read, and a cheap one: an avl lookup plus a struct.
// It is called once per render and the result reused, rather than once per
// placeholder, because dynreplacer may invoke several of the callbacks below
// and each would otherwise repeat the cross-realm call.
func scanner() mygnoscan.Scanner { return config.Scanner() }

// registerScanCallbacks adds the explorer placeholders to r.
//
// dynreplacer only invokes a callback whose placeholder actually occurs in the
// layout, so a layout using none of these costs one config.Scanner() call and
// nothing else.
func registerScanCallbacks(r *dynreplacer.Replacer) {
	s := scanner()

	r.RegisterCallback(":scan:", func() string { return s.Base() })
	r.RegisterCallback(":scan.realm:", func() string {
		return mygnoscan.Link("mygnoscan", s.Realm(realmPath))
	})
	r.RegisterCallback(":scan.me:", func() string {
		return mygnoscan.Link("my account", s.Address(admin))
	})
	r.RegisterCallback(":scan.block:", func() string {
		return mygnoscan.Link("this block", s.Block(runtime.ChainHeight()))
	})
	r.RegisterCallback(":scan.links:", func() string { return scanLinks(s) })
}

// scanLinks is the :scan.links: placeholder: everything above on one line, for
// a layout that wants the footer and does not want to lay it out by hand.
func scanLinks(s mygnoscan.Scanner) string {
	parts := []string{
		mygnoscan.Link("this realm", s.Realm(realmPath)),
		mygnoscan.Link("my account", s.Address(admin)),
		mygnoscan.Link("this block", s.Block(runtime.ChainHeight())),
	}
	return strings.Join(parts, " · ")
}

