	vals := []int64{4, 0, 9, 2, 7, 1, 1, 6, 3}

	built := FromSlice(vals)
	added := New(len(vals))
	for i, v := range vals {
		added.Add(i, v)
	}

	uassert.Equal(t, len(built.t), len(added.t))
	for i := range built.t {
		uassert.Equal(t, built.t[i], added.t[i])
	}
}

