	tr := FromSlice([]int64{1, 2, 3, 4})

	tr.Add(1, 10)
	uassert.Equal(t, int64(12), tr.At(1))
	uassert.Equal(t, int64(20), tr.Total())

	old := tr.Set(1, 2)
	uassert.Equal(t, int64(12), old)
